const esc=s=>String(s??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m]));
const normalize=s=>String(s??"").trim().replace(/[يى]/g,"ی").replace(/ك/g,"ک").replace(/[‌\s]+/g," ");
const digits=s=>String(s??"").replace(/[۰-۹]/g,d=>"۰۱۲۳۴۵۶۷۸۹".indexOf(d)).replace(/[٠-٩]/g,d=>"٠١٢٣٤٥٦٧٨٩".indexOf(d));

function div(a,b){return ~~(a/b)} function mod(a,b){return a-~~(a/b)*b}
function jalCal(jy){const breaks=[-61,9,38,199,426,686,756,818,1111,1181,1210,1635,2060,2097,2192,2262,2324,2394,2456,3178];let bl=breaks.length,gy=jy+621,leapJ=-14,jp=breaks[0],jm,jump,n,i;if(jy<jp||jy>=breaks[bl-1])throw Error("Invalid Jalaali year");for(i=1;i<bl;i++){jm=breaks[i];jump=jm-jp;if(jy<jm)break;leapJ+=div(jump,33)*8+div(mod(jump,33),4);jp=jm}n=jy-jp;leapJ+=div(n,33)*8+div(mod(n,33)+3,4);if(mod(jump,33)===4&&jump-n===4)leapJ++;const leapG=div(gy,4)-div((div(gy,100)+1)*3,4)-150;const march=20+leapJ-leapG;if(jump-n<6)n=n-jump+div(jump+4,33)*33;let leap=mod(mod(n+1,33)-1,4);if(leap===-1)leap=4;return{leap,gy,march}}
function g2d(gy,gm,gd){let d=div((gy+div(gm-8,6)+100100)*1461,4)+div(153*mod(gm+9,12)+2,5)+gd-34840408;d=d-div(div(gy+100100+div(gm-8,6),100)*3,4)+752;return d}
function d2g(jdn){let j=4*jdn+139361631;j=j+div(div(4*jdn+183187720,146097)*3,4)*4-3908;const i=div(mod(j,1461),4)*5+308;const gd=div(mod(i,153),5)+1,gm=mod(div(i,153),12)+1,gy=div(j,1461)-100100+div(8-gm,6);return{gy,gm,gd}}
function j2d(jy,jm,jd){const r=jalCal(jy);return g2d(r.gy,3,r.march)+(jm-1)*31-div(jm,7)*(jm-7)+jd-1}
function parseJalali(value){const x=digits(value).trim();const m=x.match(/^(\d{4})[\/-](\d{1,2})[\/-](\d{1,2})(?:\s+(\d{1,2}):?(\d{2})?)?/);if(!m)return null;try{const g=d2g(j2d(+m[1],+m[2],+m[3]));return new Date(Date.UTC(g.gy,g.gm-1,g.gd,+(m[4]||0),+(m[5]||0)))}catch{return null}}
function diffHours(admit,discharge){const a=parseJalali(admit),d=parseJalali(discharge);if(!a||!d)return null;return Math.round(((a-d)/36e5)*100)/100}
function monthKey(s){const m=digits(s).match(/^(\d{4})[\/-](\d{1,2})/);return m?`${m[1]}/${String(m[2]).padStart(2,"0")}`:"نامشخص"}
const PERSIAN_MONTHS={"01":"فروردین","02":"اردیبهشت","03":"خرداد","04":"تیر","05":"مرداد","06":"شهریور","07":"مهر","08":"آبان","09":"آذر","10":"دی","11":"بهمن","12":"اسفند"};
function monthNumber(s){const k=monthKey(s);return k.includes("/")?k.split("/")[1]:"نامشخص"}
function monthName(s){return PERSIAN_MONTHS[monthNumber(s)]||"نامشخص"}
function yearKey(s){const k=monthKey(s);return k.includes("/")?k.split("/")[0]:"نامشخص"}
function caseId(o){return [o.nationalId||"missing",o.admissionDate,o.previousDischargeDate,o.admissionDept].join("|")}
function makeCase(row){const o={name:String(row[0]??""),nationalId:String(row[1]??"").padStart(row[1]?10:0,"0"),visitCount:Number(row[2]||0),admissionDept:String(row[3]??""),dischargeDept:String(row[4]??""),admissionDate:String(row[5]??""),previousDischargeDate:String(row[6]??"")};o.hours=diffHours(o.admissionDate,o.previousDischargeDate);o.timeMissing=!/\d{1,2}:\d{2}/.test(digits(o.admissionDate))||!/\d{1,2}:\d{2}/.test(digits(o.previousDischargeDate));o.incomplete=!o.name||!o.nationalId||!o.admissionDept||!o.dischargeDept||!o.admissionDate||!o.previousDischargeDate;o.id=caseId(o);o.status=o.incomplete?"incomplete":"pending";o.review={dischargeType:"",previousReason:"",newReason:"",relation:"",result:"",visitOutcome:"",lengthOfStay:"",notes:"",reviewer:"",reviewedAt:""};return o}
function qualifies(c){if(c.incomplete||c.hours===null||c.hours<0)return false;return state.settings.includeExact?c.hours<=state.settings.threshold:c.hours<state.settings.threshold}

function openDb(){return new Promise((resolve,reject)=>{const r=indexedDB.open("chamran-readmission-48h",1);r.onupgradeneeded=()=>{r.result.createObjectStore("store")};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function dbGet(){const db=await openDb();return new Promise(res=>{const t=db.transaction("store"),r=t.objectStore("store").get("state");r.onsuccess=()=>res(r.result);r.onerror=()=>res(null)})}
async function dbSet(){const db=await openDb();return new Promise((res,rej)=>{const t=db.transaction("store","readwrite");t.objectStore("store").put(state,"state");t.oncomplete=res;t.onerror=()=>rej(t.error)})}
async function save(){await dbSet();$("#saveState").textContent="آخرین ذخیره: "+new Date().toLocaleTimeString("fa-IR",{hour:"2-digit",minute:"2-digit"})}

function seed(){state.cases=SAMPLE_ROWS.map(makeCase);state.imports=[{name:"داده‌های فرضی اولیه",at:today(),rows:SAMPLE_ROWS.length,eligible:state.cases.filter(qualifies).length,status:"نمونه آزمایشی"}]}
async function init(){const saved=await dbGet();if(saved&&Array.isArray(saved.cases)){state={...state,...saved};state.settings={threshold:48,includeExact:false,...saved.settings};state.baseLists={...structuredClone(DEFAULT_BASE),...(saved.baseLists||{})};state.cases.forEach(c=>{if(LABELS[c.review?.relation])c.review.relation=LABELS[c.review.relation]})}else{seed();await save()}syncDepartments();bind();renderAll();registerWebMCP();if("serviceWorker" in navigator)navigator.serviceWorker.register("sw.js").catch(()=>{})}

