function showView(name){$$(".view").forEach(v=>v.classList.toggle("active",v.id===`view-${name}`));$$(".nav-item").forEach(b=>b.classList.toggle("active",b.dataset.view===name));const titles={dashboard:["داشبورد","نمای کلی پرونده‌های بستری مجدد زیر ۴۸ ساعت"],import:["ورود فایل اکسل","دریافت خروجی سیستم آمار و شناسایی موارد واجد شرایط"],cases:["بررسی پرونده‌ها","ثبت علت ترخیص قبلی و علت پذیرش جدید"],reports:["گزارش بررسی پرونده‌ها","مرور اطلاعات ثبت‌شده برای هر پرونده"],analytics:["گزارش تحلیلی","تحلیل ماهانه اطلاعات گزارش بررسی پرونده‌ها"],base:["اطلاعات پایه","مدیریت مقادیر فهرست‌های کشویی برنامه"],settings:["تنظیمات","قاعده تشخیص و پشتیبان‌گیری اطلاعات"]};$("#pageTitle").textContent=titles[name][0];$("#pageSubtitle").textContent=titles[name][1];$("#sidebar").classList.remove("open");if(name==="cases")renderCases();if(name==="reports")renderReports();if(name==="analytics")renderAnalytics();if(name==="base")renderBaseLists()}
function options(el,vals,current){el.innerHTML=el.options[0]?.outerHTML||"";vals.forEach(v=>el.insertAdjacentHTML("beforeend",`<option value="${esc(v)}">${esc(v)}</option>`));if(current&&[...el.options].some(o=>o.value===current))el.value=current}
function renderAll(){syncDepartments();const dischargeDepts=[...new Set(state.cases.map(c=>c.dischargeDept).filter(Boolean))].sort(),admissionDepts=[...new Set(state.cases.map(c=>c.admissionDept).filter(Boolean))].sort(),allDepts=[...new Set([...state.baseLists.departments,...dischargeDepts,...admissionDepts])].sort(),months=[...new Set(state.cases.map(c=>monthKey(c.admissionDate)))].sort();options($("#dashDept"),allDepts,$("#dashDept").value);options($("#caseDept"),allDepts,$("#caseDept").value);options($("#dashMonth"),months,$("#dashMonth").value);options($("#analyticsMonth"),months,$("#analyticsMonth").value);options($("#analyticsAdmissionDept"),allDepts,$("#analyticsAdmissionDept").value);options($("#reportRelation"),state.baseLists.relations,$("#reportRelation").value);$("#requiredColumns").innerHTML=REQUIRED_HEADERS.map(x=>`<span>✓ ${x}</span>`).join("");renderDashboard();renderCases();renderReports();renderAnalytics();renderBaseLists();renderImportHistory();const pending=state.cases.filter(c=>qualifies(c)&&c.status!=="completed").length;$("#navPending").textContent=fa(pending)}
function selectedDashboard(){return state.cases.filter(c=>($("#dashMonth").value==="all"||monthKey(c.admissionDate)===$("#dashMonth").value)&&($("#dashDept").value==="all"||c.dischargeDept===$("#dashDept").value))}
function renderDashboard(){const all=selectedDashboard(),eligible=all.filter(qualifies),done=eligible.filter(c=>c.status==="completed"),pending=eligible.filter(c=>c.status!=="completed"),personal=done.filter(c=>c.review.dischargeType==="رضایت شخصی").length,related=done.filter(c=>["related","probable"].includes(c.review.relation)).length;const k=[ ["کل ردیف‌های واردشده",all.length,"در محدوده فیلتر","#0b4f6c"],["موارد زیر ۴۸ ساعت",eligible.length,`${state.settings.includeExact?"تا":"کمتر از"} ${fa(state.settings.threshold)} ساعت`,"#16866b"],["بررسی تکمیل‌شده",done.length,eligible.length?`${fa(Math.round(done.length/eligible.length*100))}٪ از موارد`:"بدون مورد","#2876a3"],["باقی‌مانده بررسی",pending.length,"نیازمند مراجعه به پرونده","#d58a18"],["ترخیص با رضایت شخصی",personal,done.length?`${fa(Math.round(personal/done.length*100))}٪ از بررسی‌شده‌ها`:"هنوز ثبت نشده","#c83f49"] ];$("#kpiGrid").innerHTML=k.map(x=>`<div class="kpi" style="--accent:${x[3]}"><span class="label">${x[0]}</span><strong>${fa(x[1])}</strong><small>${x[2]}</small></div>`).join("");
 const pct=eligible.length?Math.round(done.length/eligible.length*100):0;$("#reviewProgress").innerHTML=`<div class="progress-top"><span>پیشرفت بررسی</span><strong>${fa(pct)}٪</strong></div><div class="progress-track"><div class="progress-fill" style="width:${pct}%"></div></div><div class="progress-legend"><span><i style="background:#16866b"></i>${fa(done.length)} تکمیل‌شده</span><span><i style="background:#d58a18"></i>${fa(pending.length)} باقی‌مانده</span><span><i style="background:#7a8990"></i>${fa(all.filter(c=>c.incomplete).length)} ناقص</span></div>`;
 const med=done.filter(c=>c.review.dischargeType==="نظر پزشک").length,unk=Math.max(0,done.length-med-personal),den=Math.max(1,done.length),p1=med/den*100,p2=personal/den*100;$("#dischargeChart").innerHTML=`<div class="donut" style="background:conic-gradient(#16866b 0 ${p1}%,#c83f49 ${p1}% ${p1+p2}%,#cbd6db ${p1+p2}% 100%)"><div class="donut-center"><strong>${fa(done.length)}</strong><span>پرونده</span></div></div><div class="chart-legend"><span><i style="background:#16866b"></i>نظر پزشک: ${fa(med)}</span><span><i style="background:#c83f49"></i>رضایت شخصی: ${fa(personal)}</span><span><i style="background:#cbd6db"></i>نامشخص: ${fa(unk)}</span></div>`;
 const counts={};eligible.forEach(c=>counts[c.dischargeDept]=(counts[c.dischargeDept]||0)+1);const max=Math.max(1,...Object.values(counts));$("#departmentBars").innerHTML=Object.entries(counts).sort((a,b)=>b[1]-a[1]).slice(0,7).map(([d,n])=>`<div class="bar-row"><span>${esc(d)}</span><div class="bar-track"><div class="bar-fill" style="width:${n/max*100}%"></div></div><b>${fa(n)}</b></div>`).join("")||`<div class="empty-row">داده‌ای وجود ندارد</div>`;
 const needs=[{t:"پرونده بررسی‌نشده",n:eligible.filter(c=>c.status==="pending").length},{t:"اطلاعات ورودی ناقص",n:all.filter(c=>c.incomplete).length},{t:"نیازمند نظر پزشک",n:eligible.filter(c=>c.status==="needs_doctor").length},{t:"پذیرش مرتبط یا محتمل",n:related}];$("#attentionList").innerHTML=needs.map(x=>`<div class="attention-item"><span>${x.t}</span><b>${fa(x.n)}</b></div>`).join("")}
function filteredCases(){const q=normalize($("#caseSearch").value),status=$("#caseStatus").value,dept=$("#caseDept").value,only=$("#onlyUnder48").checked;return state.cases.filter(c=>(!q||normalize(c.name).includes(q)||digits(c.nationalId).includes(digits(q)))&&(status==="all"||c.status===status)&&(dept==="all"||c.dischargeDept===dept)&&(!only||qualifies(c)))}
function renderCases(){if(!$("#caseList"))return;const list=filteredCases();$("#caseCount").textContent=`${fa(list.length)} پرونده`;$("#caseList").innerHTML=list.map(c=>`<button class="case-card ${state.selectedId===c.id?"active":""}" data-id="${esc(c.id)}"><div class="case-row"><strong>${esc(c.name||"نام ثبت نشده")}</strong><span class="badge ${c.status}">${LABELS[c.status]}</span></div><div class="case-row"><small>کد ملی: ${maskId(c.nationalId)}</small><small>${formatHours(c)}</small></div><small>${esc(c.dischargeDept||"بخش نامشخص")} ← ${esc(c.admissionDept||"بخش نامشخص")}</small></button>`).join("")||`<div class="empty-row">پرونده‌ای مطابق فیلتر پیدا نشد.</div>`;$$('.case-card').forEach(b=>b.onclick=()=>{state.selectedId=b.dataset.id;renderCases();renderReview()});renderReview()}
function maskId(id){return id?`${id.slice(0,3)}••••${id.slice(-3)}`:"ثبت نشده"} function formatHours(c){return c.hours===null?"زمان نامشخص":`${fa(c.hours)} ساعت`}
function renderReview(){
 const c=state.cases.find(x=>x.id===state.selectedId);
 if(!c){$("#reviewPanel").innerHTML=`<div class="empty-state"><div>☷</div><h2>یک پرونده را انتخاب کنید</h2><p>اطلاعات پرونده و فرم بررسی در این قسمت نمایش داده می‌شود.</p></div>`;return}
 const r=c.review||{};
 $("#reviewPanel").innerHTML=`<div class="patient-head"><div><h2>${esc(c.name||"نام ثبت نشده")}</h2><p>کد ملی: ${esc(c.nationalId||"ثبت نشده")} · تعداد مراجعه: ${fa(c.visitCount)}</p></div><span class="badge ${c.status}">${LABELS[c.status]||c.status}</span></div><div class="patient-grid"><div><span>بخش ترخیص قبلی</span><strong>${esc(c.dischargeDept||"ثبت نشده")}</strong></div><div><span>بخش پذیرش جدید</span><strong>${esc(c.admissionDept||"ثبت نشده")}</strong></div><div><span>ترخیص قبلی</span><strong>${esc(c.previousDischargeDate||"ثبت نشده")}</strong></div><div><span>پذیرش جدید</span><strong>${esc(c.admissionDate||"ثبت نشده")}</strong></div><div><span>فاصله محاسبه‌شده</span><strong>${formatHours(c)}</strong></div><div><span>وضعیت تشخیص</span><strong>${c.incomplete?"اطلاعات ناقص":qualifies(c)?"واجد شرایط":"بیشتر از حد"}</strong></div><div><span>ماه گزارش</span><strong>${monthName(c.admissionDate)}</strong></div><div><span>شناسه پرونده</span><strong>${esc(c.id.slice(0,18))}…</strong></div></div><form class="review-form" id="reviewForm"><h3>اطلاعات استخراج‌شده از پرونده</h3><div class="form-grid"><label>نوع ترخیص قبلی<select name="dischargeType" required>${selectOpts(["",...state.baseLists.dischargeTypes],r.dischargeType)}</select></label><label>ارتباط پذیرش جدید با بستری قبلی<select name="relation" required>${selectOpts(["",...state.baseLists.relations],r.relation)}</select></label><label class="full">علت ترخیص قبلی<select name="previousReason" required>${selectOpts(["",...state.baseLists.previousReasons],r.previousReason)}</select></label><label class="full">علت پذیرش جدید<select name="newReason" required>${selectOpts(["",...state.baseLists.newReasons],r.newReason)}</select></label><label>نتیجه بررسی<input name="result" value="${esc(r.result)}" placeholder="جمع‌بندی کوتاه" /></label><label>نام یا کد بررسی‌کننده<input name="reviewer" value="${esc(r.reviewer)}" /></label><label class="full">توضیحات<textarea name="notes" placeholder="توضیحات تکمیلی پرونده">${esc(r.notes)}</textarea></label><label>وضعیت بررسی<select name="status">${selectObj({in_progress:"در حال بررسی",completed:"تکمیل شده",needs_doctor:"نیازمند بررسی پزشک",pending:"بررسی نشده"},c.status==="incomplete"?"in_progress":c.status)}</select></label></div><div class="form-actions"><button type="button" class="btn secondary" id="saveDraft">ذخیره موقت</button><button class="btn primary" type="submit">ثبت و تکمیل بررسی</button></div></form>`;
 $("#reviewForm").onsubmit=e=>saveReview(e,true);$("#saveDraft").onclick=e=>saveReview(e,false)
}
function selectOpts(arr,val){return arr.map(x=>`<option value="${esc(x)}" ${x===val?"selected":""}>${esc(x||"انتخاب کنید")}</option>`).join("")}function selectObj(o,val){return Object.entries(o).map(([k,v])=>`<option value="${k}" ${k===val?"selected":""}>${v}</option>`).join("")}
async function saveReview(e,complete){e.preventDefault();const c=state.cases.find(x=>x.id===state.selectedId),fd=new FormData($("#reviewForm"));c.review={...c.review,...Object.fromEntries(fd.entries()),reviewedAt:today()};c.status=complete?"completed":fd.get("status")||"in_progress";if(complete&&(!c.review.dischargeType||!c.review.previousReason||!c.review.newReason||!c.review.relation)){toast("چهار فیلد اصلی را کامل کنید");return}await save();renderAll();toast(complete?"بررسی پرونده تکمیل شد":"اطلاعات موقت ذخیره شد")}
function renderImportHistory(){$("#importHistory").innerHTML=state.imports.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.at)}</td><td>${fa(x.rows)}</td><td>${fa(x.eligible)}</td><td><span class="badge completed">${esc(x.status)}</span></td></tr>`).join("")||`<tr><td colspan="5" class="empty-row">هنوز فایلی وارد نشده است.</td></tr>`}
async function importFile(file){if(!file.name.toLowerCase().endsWith(".xlsx")){toast("فقط فایل xlsx قابل قبول است");return}try{const matrix=await readFirstSheet(await file.arrayBuffer());if(matrix.length<2)throw Error("فایل بدون داده است");const heads=matrix[0].map(normalize),map=REQUIRED_HEADERS.map(h=>{const aliases=HEADER_ALIASES[h].map(normalize);return heads.findIndex(x=>aliases.includes(x))});const missing=REQUIRED_HEADERS.filter((_,i)=>map[i]<0);if(missing.length)throw Error("ستون‌های پیدا نشده: "+missing.join("، "));const incoming=matrix.slice(1).filter(r=>r.some(v=>String(v??"").trim())).map(r=>makeCase(map.map(i=>r[i])));let added=0,updated=0;incoming.forEach(c=>{const old=state.cases.find(x=>x.id===c.id);if(old){Object.assign(old,{...c,review:old.review,status:old.status});updated++}else{state.cases.push(c);added++}});const eligible=incoming.filter(qualifies).length;state.imports.unshift({name:file.name,at:today(),rows:incoming.length,eligible,status:"موفق"});await save();$("#importResult").classList.remove("hidden");$("#importResult").innerHTML=`<div class="result-grid"><div class="result-stat"><strong>${fa(incoming.length)}</strong><span>ردیف خوانده‌شده</span></div><div class="result-stat"><strong>${fa(eligible)}</strong><span>واجد شرایط</span></div><div class="result-stat"><strong>${fa(added)}</strong><span>پرونده جدید</span></div><div class="result-stat"><strong>${fa(updated)}</strong><span>ردیف تکراری/به‌روزرسانی</span></div></div>`;renderAll();toast("فایل با موفقیت پردازش شد")}catch(err){$("#importResult").classList.remove("hidden");$("#importResult").innerHTML=`<div class="attention-item"><span>${esc(err.message||"خواندن فایل ممکن نشد")}</span></div>`;toast("ورود فایل انجام نشد")}}
async function readFirstSheet(buf){const zip=await JSZip.loadAsync(buf),parser=new DOMParser();let shared=[];if(zip.file("xl/sharedStrings.xml")){const doc=parser.parseFromString(await zip.file("xl/sharedStrings.xml").async("text"),"text/xml");shared=[...doc.getElementsByTagName("si")].map(si=>[...si.getElementsByTagName("t")].map(t=>t.textContent).join(""))}const wb=parser.parseFromString(await zip.file("xl/workbook.xml").async("text"),"text/xml"),sheet=wb.getElementsByTagName("sheet")[0],rid=sheet.getAttribute("r:id");const rel=parser.parseFromString(await zip.file("xl/_rels/workbook.xml.rels").async("text"),"text/xml"),target=[...rel.getElementsByTagName("Relationship")].find(x=>x.getAttribute("Id")===rid)?.getAttribute("Target");if(!target)throw Error("شیت Excel شناسایی نشد");const path=target.startsWith("/")?target.slice(1):`xl/${target.replace(/^\.\//,"")}`;const doc=parser.parseFromString(await zip.file(path).async("text"),"text/xml"),out=[];for(const row of [...doc.getElementsByTagName("row")]){const arr=[];for(const c of [...row.getElementsByTagName("c")]){const ref=c.getAttribute("r"),col=ref.replace(/\d/g,"").split("").reduce((n,ch)=>n*26+ch.charCodeAt(0)-64,0)-1,t=c.getAttribute("t");let v="";if(t==="inlineStr")v=[...c.getElementsByTagName("t")].map(x=>x.textContent).join("");else{const node=c.getElementsByTagName("v")[0];v=node?node.textContent:"";if(t==="s")v=shared[+v]??"";else if(t!=="str"&&v!==""&&!isNaN(v))v=Number(v)}arr[col]=v}out.push(arr)}return out}
function renderReports(){const st=$("#reportStatus").value,rel=$("#reportRelation").value;let list=state.cases.filter(c=>(st==="all"||c.status===st)&&(rel==="all"||c.review.relation===rel));const eligible=state.cases.filter(qualifies),done=eligible.filter(c=>c.status==="completed"),related=done.filter(c=>["related","probable"].includes(c.review.relation));$("#reportKpis").innerHTML=[["واجد شرایط",eligible.length,"#0b4f6c"],["بررسی‌شده",done.length,"#16866b"],["مرتبط یا محتمل",related.length,"#d58a18"],["اطلاعات ناقص",state.cases.filter(c=>c.incomplete).length,"#c83f49"]].map(x=>`<div class="kpi" style="--accent:${x[2]}"><span class="label">${x[0]}</span><strong>${fa(x[1])}</strong></div>`).join("");$("#reportTable").innerHTML=list.map(c=>`<tr><td>${esc(c.name||"نامشخص")}</td><td>${esc(c.dischargeDept||"—")}</td><td>${formatHours(c)}</td><td>${esc(c.review.dischargeType||"—")}</td><td>${esc(c.review.newReason||"—")}</td><td>${LABELS[c.review.relation]||"—"}</td><td><span class="badge ${c.status}">${LABELS[c.status]}</span></td></tr>`).join("")||`<tr><td colspan="7" class="empty-row">داده‌ای وجود ندارد.</td></tr>`}
function backupStamp(date=new Date()){const parts=Object.fromEntries(new Intl.DateTimeFormat("fa-IR-u-ca-persian-nu-latn",{year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit",second:"2-digit",hourCycle:"h23"}).formatToParts(date).filter(x=>x.type!=="literal").map(x=>[x.type,digits(x.value)]));return`${parts.year}-${parts.month}-${parts.day}_${parts.hour}-${parts.minute}-${parts.second}`}
function exportJson(){download(new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:"application/json"}),`پشتیبان-بستری-مجدد-${backupStamp()}.json`);toast("فایل پشتیبان ساخته شد")}
async function restoreJson(e){try{const x=JSON.parse(await e.target.files[0].text());if(!Array.isArray(x.cases))throw Error();state={...state,...x,baseLists:{...structuredClone(DEFAULT_BASE),...(x.baseLists||{})}};syncDepartments();await save();renderAll();toast("اطلاعات بازیابی شد")}catch{toast("فایل پشتیبان معتبر نیست")}e.target.value=""}
function download(blob,name){const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function exportXlsx(){const headers=[...REQUIRED_HEADERS,"فاصله زمانی (ساعت)","واجد شرایط زیر ۴۸ ساعت","نوع ترخیص قبلی","علت ترخیص قبلی","علت پذیرش جدید","ارتباط با بستری قبلی","نتیجه بررسی","توضیحات","بررسی‌کننده","تاریخ بررسی","وضعیت بررسی"];const rows=state.cases.map(c=>[c.name,c.nationalId,c.visitCount,c.admissionDept,c.dischargeDept,c.admissionDate,c.previousDischargeDate,c.hours??"",qualifies(c)?"بله":"خیر",c.review.dischargeType,c.review.previousReason,c.review.newReason,LABELS[c.review.relation]||"",c.review.result,c.review.notes,c.review.reviewer,c.review.reviewedAt,LABELS[c.status]]);const zip=new JSZip(),sheetData=[headers,...rows].map((r,ri)=>`<row r="${ri+1}">${r.map((v,ci)=>cellXml(v,ci,ri)).join("")}</row>`).join("");zip.file("[Content_Types].xml",`<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/></Types>`);zip.folder("_rels").file(".rels",`<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>`);zip.folder("xl").file("workbook.xml",`<?xml version="1.0"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="گزارش بستری مجدد" sheetId="1" r:id="rId1"/></sheets></workbook>`).file("styles.xml",`<?xml version="1.0"?><styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="2"><font><sz val="11"/><name val="Arial"/></font><font><b/><color rgb="FFFFFFFF"/><sz val="11"/><name val="Arial"/></font></fonts><fills count="3"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FF0B4F6C"/><bgColor indexed="64"/></patternFill></fill></fills><borders count="1"><border/></borders><cellStyleXfs count="1"><xf/></cellStyleXfs><cellXfs count="2"><xf fontId="0" fillId="0" borderId="0" xfId="0"/><xf fontId="1" fillId="2" borderId="0" xfId="0" applyFill="1" applyFont="1"><alignment horizontal="center"/></xf></cellXfs></styleSheet>`).folder("_rels").file("workbook.xml.rels",`<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>`);zip.folder("xl").folder("worksheets").file("sheet1.xml",`<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView rightToLeft="1" workbookViewId="0"/></sheetViews><cols>${headers.map((_,i)=>`<col min="${i+1}" max="${i+1}" width="${i===14?35:18}" customWidth="1"/>`).join("")}</cols><sheetData>${sheetData}</sheetData><autoFilter ref="A1:R${rows.length+1}"/></worksheet>`);const blob=await zip.generateAsync({type:"blob",compression:"DEFLATE"});download(blob,`گزارش-بستری-مجدد-${Date.now()}.xlsx`);toast("خروجی Excel ساخته شد")}
function colName(n){let s="";for(n++;n;n=Math.floor((n-1)/26))s=String.fromCharCode(65+(n-1)%26)+s;return s}function xml(s){return String(s??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&apos;"}[m]))}function cellXml(v,c,r){const ref=colName(c)+(r+1),style=r===0?' s="1"':"";if(typeof v==="number"&&Number.isFinite(v))return `<c r="${ref}"${style}><v>${v}</v></c>`;return `<c r="${ref}" t="inlineStr"${style}><is><t>${xml(v)}</t></is></c>`}
function toast(msg){const t=$("#toast");t.textContent=msg;t.classList.add("show");clearTimeout(t._timer);t._timer=setTimeout(()=>t.classList.remove("show"),2700)}

function syncDepartments(){
 const found=state.cases.flatMap(c=>[c.dischargeDept,c.admissionDept]).filter(Boolean);
 state.baseLists.departments=[...new Set([...(state.baseLists.departments||[]),...found])].sort();
}
function reportData(){return state.cases.map(c=>({dischargeDept:c.dischargeDept||"ثبت نشده",admissionDept:c.admissionDept||"ثبت نشده",duration:c.hours,previousReason:c.review.previousReason||"ثبت نشده",newReason:c.review.newReason||"ثبت نشده",result:c.review.result||"ثبت نشده",relation:c.review.relation||"ثبت نشده",dischargeType:c.review.dischargeType||"ثبت نشده",visitOutcome:c.review.visitOutcome||"ثبت نشده",lengthOfStay:c.review.lengthOfStay===""||c.review.lengthOfStay==null?null:Number(c.review.lengthOfStay),newDiagnosis:c.newFinalDiagnosis||c.newInitialDiagnosis||"ثبت نشده",notes:c.review.notes||"",month:monthName(c.admissionDate),monthNumber:monthNumber(c.admissionDate),year:yearKey(c.admissionDate),status:c.status,caseRef:c}))}

function renderReports(){
 const st=$("#reportStatus").value,rel=$("#reportRelation").value;
 const list=reportData().filter(r=>(st==="all"||r.status===st)&&(rel==="all"||r.relation===rel));
 const eligible=state.cases.filter(qualifies),done=eligible.filter(c=>c.status==="completed"),related=done.filter(c=>["مرتبط","احتمالاً مرتبط"].includes(c.review.relation));
 $("#reportKpis").innerHTML=[["واجد شرایط",eligible.length,"#0b4f6c"],["بررسی‌شده",done.length,"#16866b"],["مرتبط یا محتمل",related.length,"#d58a18"],["اطلاعات ناقص",state.cases.filter(c=>c.incomplete).length,"#c83f49"]].map(x=>`<div class="kpi" style="--accent:${x[2]}"><span class="label">${x[0]}</span><strong>${fa(x[1])}</strong></div>`).join("");
 $("#reportTable").innerHTML=list.map(r=>`<tr><td>${esc(r.dischargeDept)}</td><td>${esc(r.admissionDept)}</td><td>${r.duration===null?"نامشخص":fa(r.duration)+" ساعت"}</td><td>${esc(r.previousReason)}</td><td>${esc(r.newReason)}</td><td>${esc(r.result)}</td><td>${esc(r.relation)}</td><td>${esc(r.dischargeType)}</td><td>${esc(r.visitOutcome)}</td><td>${r.lengthOfStay===null?"—":fa(r.lengthOfStay)}</td><td>${esc(r.notes||"—")}</td></tr>`).join("")||`<tr><td colspan="11" class="empty-row">داده‌ای وجود ندارد.</td></tr>`;
}

function renderBaseLists(){
 if(!$("#baseLists"))return;
 $("#baseLists").innerHTML=Object.entries(BASE_TITLES).map(([key,title])=>`<article class="panel base-card"><div class="panel-head"><div><h2>${title}</h2><p>${fa((state.baseLists[key]||[]).length)} مقدار ثبت‌شده</p></div></div><form class="base-add" data-key="${key}"><input aria-label="افزودن ${title}" placeholder="مقدار جدید را بنویسید"/><button class="btn primary">افزودن</button></form><div class="base-items">${(state.baseLists[key]||[]).map((v,i)=>`<span class="base-chip">${esc(v)}<button aria-label="حذف ${esc(v)}" data-key="${key}" data-index="${i}">×</button></span>`).join("")||`<span class="base-empty">مقداری ثبت نشده است.</span>`}</div></article>`).join("");
 $$(".base-add").forEach(f=>f.onsubmit=async e=>{e.preventDefault();const key=f.dataset.key,input=f.querySelector("input"),value=normalize(input.value);if(!value)return;if(state.baseLists[key].some(v=>normalize(v)===value)){toast("این مقدار قبلاً ثبت شده است");return}state.baseLists[key].push(value);state.baseLists[key].sort();input.value="";await save();renderAll();toast("مقدار جدید اضافه شد")});
 $$(".base-chip button").forEach(b=>b.onclick=async()=>{const {key,index}=b.dataset;state.baseLists[key].splice(Number(index),1);await save();renderAll();toast("مقدار حذف شد")});
}

const CHART_COLORS=["#0b4f6c","#16866b","#d58a18","#7b5da7","#c83f49","#2876a3","#758a45","#a65f37"];
function countBy(list,key){const out={};list.forEach(x=>{const v=typeof key==="function"?key(x):x[key];out[v||"ثبت نشده"]=(out[v||"ثبت نشده"]||0)+1});return out}
function simpleBars(data,order=false){const entries=Object.entries(data);if(order!=="preserve")entries.sort(order?(a,b)=>a[0].localeCompare(b[0],"fa"):(a,b)=>b[1]-a[1]);const max=Math.max(1,...entries.map(x=>x[1]));return entries.length?`<div class="simple-bars horizontal-chart">${entries.map(([k,v],i)=>`<div class="simple-bar-row"><span>${esc(k)}</span><div class="simple-bar-track"><div class="simple-bar-fill" style="width:${v/max*100}%;background:${CHART_COLORS[i%CHART_COLORS.length]}"></div></div><b>${fa(v)}</b></div>`).join("")}</div>`:`<div class="chart-empty">داده‌ای برای نمایش وجود ندارد.</div>`}
function stackedChart(list,categoryKey){const months=[...new Set(list.map(x=>x.month))].sort(),cats=[...new Set(list.map(x=>x[categoryKey]))].sort();if(!months.length)return`<div class="chart-empty">داده‌ای برای نمایش وجود ندارد.</div>`;const totals=months.map(m=>list.filter(x=>x.month===m).length),max=Math.max(1,...totals);return`<div class="stacked-wrap"><div class="stacked-bars">${months.map((m,mi)=>`<div class="stack-group"><div class="stack-column">${cats.map((cat,ci)=>{const n=list.filter(x=>x.month===m&&x[categoryKey]===cat).length;return`<div class="stack-segment" title="${esc(cat)}: ${n}" style="height:${n/max*150}px;background:${CHART_COLORS[ci%CHART_COLORS.length]}"></div>`}).join("")}</div><div class="stack-label">${esc(m)}<br>${fa(totals[mi])}</div></div>`).join("")}</div><div class="chart-keys">${cats.map((c,i)=>`<span><i style="background:${CHART_COLORS[i%CHART_COLORS.length]}"></i>${esc(c)}</span>`).join("")}</div></div>`}
function groupedHorizontalChart(list,categoryKey){
 const monthOrder=Object.values(PERSIAN_MONTHS),months=[...new Set(list.map(x=>x.month))].sort((a,b)=>monthOrder.indexOf(a)-monthOrder.indexOf(b)),categories=[...new Set(list.map(x=>x[categoryKey]))].sort();
 if(!months.length||!categories.length)return`<div class="chart-empty">داده‌ای برای نمایش وجود ندارد.</div>`;
 const values=categories.flatMap(cat=>months.map(m=>list.filter(x=>x[categoryKey]===cat&&x.month===m).length)),max=Math.max(1,...values);
 return`<div class="hbar-groups">${categories.map(cat=>`<section class="hbar-group"><h3>${esc(cat)}</h3><div class="hbar-series">${months.map((m,i)=>{const n=list.filter(x=>x[categoryKey]===cat&&x.month===m).length;return`<div class="hbar-row"><span>${esc(m)}</span><div class="hbar-track"><div class="hbar-fill" style="width:${n/max*100}%;background:${CHART_COLORS[i%CHART_COLORS.length]}"></div></div><b>${fa(n)}</b></div>`}).join("")}</div></section>`).join("")}</div><div class="chart-keys">${months.map((m,i)=>`<span><i style="background:${CHART_COLORS[i%CHART_COLORS.length]}"></i>${esc(m)}</span>`).join("")}</div>`
}
function pieChart(data){
 const entries=Object.entries(data).sort((a,b)=>b[1]-a[1]),total=entries.reduce((s,x)=>s+x[1],0);
 if(!total)return`<div class="chart-empty">داده‌ای برای نمایش وجود ندارد.</div>`;
 let cursor=0;const stops=entries.map(([_,value],i)=>{const start=cursor;cursor+=value/total*100;return`${CHART_COLORS[i%CHART_COLORS.length]} ${start}% ${cursor}%`}).join(",");
 return`<div class="analytics-pie-wrap"><div class="analytics-pie" style="background:conic-gradient(${stops})"><div><strong>${fa(total)}</strong><span>پرونده</span></div></div><div class="pie-legend">${entries.map(([label,value],i)=>`<div><i style="background:${CHART_COLORS[i%CHART_COLORS.length]}"></i><span>${esc(label)}</span><b>${fa(value)} (${fa(Math.round(value/total*100))}٪)</b></div>`).join("")}</div></div>`
}
