async function saveReview(e,complete){e.preventDefault();let c=state.cases.find(x=>x.id===state.selectedId);if(!c)return;const fd=new FormData($("#reviewForm"));c.review={...c.review,...Object.fromEntries(fd.entries()),reviewedAt:today()};if(c.review.lengthOfStay!=="")c.review.lengthOfStay=Math.max(0,Number(c.review.lengthOfStay)||0);if(c.sourceType==="hs"){const prev=(state.encounters||[]).find(x=>x.visitNumber===c.previousVisitNumber),next=(state.encounters||[]).find(x=>x.visitNumber===c.newVisitNumber),fresh=buildHsCase(prev,next,c);Object.assign(c,fresh)}if(complete&&(!c.review.dischargeType||!c.review.previousReason||!c.review.newReason||!c.review.relation||!c.review.visitOutcome)){toast("فیلدهای اصلی و نتیجه مراجعه را کامل کنید");return}const requested=fd.get("status")||"in_progress";c.status=complete?"completed":requested==="needs_time"&&c.intervalClass!=="needs_time"?"in_progress":requested;await save();renderAll();toast(complete?"بررسی پرونده تکمیل شد":"اطلاعات موقت ذخیره شد")}
