/* Version 4: presentation-ready charts and selective PowerPoint export */
const PRESENTATION_COLORS=["#123B5D","#18A999","#3B82C4","#F2B134","#E76F51","#6C63A8","#2F7D8C","#9C5C8F"];
const svgTextStyle="font-family:Tahoma,Arial,sans-serif;fill:#334155";
