 const groups={};rows.forEach(r=>{if(!r.relation||r.relation==="ثبت نشده")return;const key=r.admissionDept||"ثبت نشده";groups[key]??={reviewed:0,related:0};groups[key].reviewed++;if(["مرتبط","احتمالاً مرتبط"].includes(r.relation))groups[key].related++});
