 const ticks=[0,25,50,75,100].map(v=>{const x=barRight-plotW+plotW*v/100;return`<line x1="${x}" y1="${top-8}" x2="${x}" y2="${height-bottom}" stroke="#DFE8ED"/><text x="${x}" y="${height-12}" text-anchor="middle" style="${svgTextStyle};font-size:11px">${fa(v)}٪</text>`}).join("");
 const bars=entries.map(([label,v],i)=>{const y=top+i*rowH,w=v.rate/100*plotW,c=PRESENTATION_COLORS[i%PRESENTATION_COLORS.length];return`<rect x="${barRight-w}" y="${y}" width="${Math.max(2,w)}" height="27" rx="7" fill="${c}"/><text x="${barRight-w-10}" y="${y+19}" text-anchor="end" style="${svgTextStyle};font-size:12px;font-weight:700">${fa(v.rate)}٪</text><text x="${labelX}" y="${y+13}" text-anchor="end" direction="rtl" unicode-bidi="plaintext" style="${svgTextStyle};font-size:12px;font-weight:700">${esc(label)}</text><text x="${labelX}" y="${y+29}" text-anchor="end" direction="rtl" style="${svgTextStyle};font-size:10px;fill:#64748B">${fa(v.related)} از ${fa(v.reviewed)} پرونده</text>`}).join("");
