 $("#monthlyChart").innerHTML=verticalColumnChart(monthlyCounts,true);$("#dischargeDeptChart").innerHTML=groupedColumnChart(filtered,"dischargeDept");$("#admissionDeptChart").innerHTML=groupedColumnChart(filtered,"admissionDept");$("#durationChart").innerHTML=verticalColumnChart(countBy(filtered,r=>r.duration===null?"نامشخص":r.duration<12?"کمتر از ۱۲ ساعت":r.duration<24?"۱۲ تا ۲۴ ساعت":r.duration<36?"۲۴ تا ۳۶ ساعت":r.duration<=48?"۳۶ تا ۴۸ ساعت":"بیشتر از ۴۸ ساعت"));$("#relationChart").innerHTML=donutSvg(countBy(filtered,"relation"));$("#dischargeTypeAnalytics").innerHTML=donutSvg(countBy(filtered,"dischargeType"));$("#visitOutcomeChart").innerHTML=donutSvg(countBy(filtered,"visitOutcome"));$("#diagnosisChart").innerHTML=rtlDiagnosisChart(diagnoses);$("#managementRelationChart").innerHTML=managementRelationRateChart(filtered);
